def get_grade(avg):
    if avg >= 90:
        return "A"
    elif avg >= 80:
        return "B"
    elif avg >= 70:
        return "C"
    elif avg >= 60:
        return "D"
    return "F"


def read_students(n):
    students = []
    for _ in range(n):
        parts = input().split()
        scores = [int(x) for x in parts[1:]]
        students.append({"name": parts[0], "avg": sum(scores) / len(scores)})
    return students


def print_report(students):
    for s in students:
        print(f"{s['name']} {s['avg']:.1f} {get_grade(s['avg'])}")
    class_avg = sum(s["avg"] for s in students) / len(students)
    print(f"반 평균: {class_avg:.1f}")
    best = max(students, key=lambda s: s["avg"])
    print(f"1등: {best['name']}")


n = int(input())
students = read_students(n)
print_report(students)
